query GetProjects {
  projects {
    ...ProjectFields
    __typename
  }
}

fragment ProjectFields on Project {
  projectId
  name
  description
  createdAt
  updatedAt
  workspaces {
    workspaceId
    workspaceRootPath
    displayName
    description
    addedAt
    availability
    __typename
  }
  taskCount
  openTaskCount
  __typename
}

query GetProjectsCapability {
  projectsCapability {
    ...ProjectsCapabilityFields
    __typename
  }
}

fragment ProjectsCapabilityFields on ProjectsCapability {
  enabled
  settingKey
  source
  __typename
}

query GetSkills {
  skills {
    name
    description
    content
    rootPath
    fileCount
    isReadonly
    isDisabled
